  List<TaskBlock> cardsOfTurn(int t) =>
      _cards.where((c) => c.turn == t).toList();

  int _countOfTurn(int t, bool Function(TaskBlock) test) =>
      cardsOfTurn(t).where(test).length;

  /// Live cards, newest first.
  List<TaskBlock> get liveCards => _cards
      .where((c) => !taskBlockStateIsTerminal(c.state))
      .toList()
      .reversed
      .toList();

  /// Whether the current turn's bucket exceeds the collapse threshold
  /// (more than 3 jobs in one turn).
  bool get collapsed => cardsOfTurn(turn).length > 3;

  /// The transient job-board region: one summary line per collapsed bucket
  /// that still has live cards (current turn first), plus up to
  /// [_maxLiveRows] live rows. Buckets with 3 or fewer jobs show rows
  /// only. [width] threads the gh-1446 clip-priority fit into the summary
  /// line (AC6: lost > parens > icon); null keeps the line unclipped.
  List<String> liveLines({int? width}) {
    final lines = <String>[];
    final turnsWithLive =
        _cards
            .where((c) => !taskBlockStateIsTerminal(c.state))
            .map((c) => c.turn)
            .toSet()
            .toList()
          ..sort((a, b) => b.compareTo(a));
    for (final t in turnsWithLive) {
      if (cardsOfTurn(t).length <= 3) continue;
      final line = shellJobLiveSummaryLine(
        running: _countOfTurn(t, (c) => c.state == TaskBlockState.running),
        lost: _countOfTurn(t, (c) => c.state == TaskBlockState.lost),
        width: width,
      );
      if (line == null) continue;
      if (t != turn) {
        // Frozen at first print (issue #539): the live region re-renders
        // on every job mutation, and a re-derived older row mutates across
        // frames — a frozen transcript must never show moving counts. The
        // `· older` suffix marks provenance (gh-1446 retires the count
        // noise, not the turn marker).
        lines.add(_frozenOlderSummaries.putIfAbsent(t, () => '$line · older'));
        continue;
      }
      lines.add(line);
    }
    for (final card in liveCards.take(_maxLiveRows)) {
      // No fixed char cap (issue #638 AC3): the TUI frame clips at the
      // LIVE viewport width and recomputes on resize; the preview stays
      // one physical line (issue #599).
      lines.add('↳ ${card.id} · ${shellJobCommandPreview(card.label)}');
    }
    return lines;
  }

